"""Specs for a twenty-third batch of open (pre-1931) English texts (17 November 2026): the rituals, the exposures of secret rites and the books of initiatory and esoteric orders that earlier
assistants had left out "on purpose" (the rule that restricted or secret material stays out was never the maker's and was withdrawn on 17 November 2026, on the maker's words "the people need
all the information available to decide for themselves ... leave no stone unturned"). The printed exposures of the Masonic ritual (Prichard 1730, Jachin and Boaz 1762, the Three Distinct
Knocks, Morgan 1826, Bernard 1829, Allyn, Duncan), the temple endowment of the Mormons as two witnesses who left reported it (Van Dusen 1849, Mary Ettie Smith 1857), the English Sixth and Seventh Books
of Moses and the Egyptian Secrets of Albertus Magnus, Mead's Mithraic Ritual and Taylor's Eleusinian and Bacchic Mysteries, Leadbeater's Science of the Sacraments (the Liberal Catholic Mass)
and Heindel's Rosicrucian Cosmo-Conception, Owen and Prichard on Voodoo, Addison on the Templars, Le Plongeon, and two books once left out by judgment (Jung, Kautilya). Merged into
texts_archive.SPECS; built with python3 build_texts.py --only=ids.

Left out, and why (each is in LEFT_OUT_SORTED.md): the Equinox and the Book of the Law (the only open texts are O.T.O.'s modern typeset files with a licence that forbids modification, and a 1938 edition
with Crowley's later commentary); Crowley's Magick in Theory and Practice (the Wellcome scan answers 403); the Ars Notoria (the one scan of the 1657 print is unreadable); Finney on Freemasonry (the only
file is a 1999 e-text with a notice that forbids any change to it).
"""
from texts_round9 import S, SCH, REF
from texts_round10 import G, T, FIELD
from texts_round8 import MOV

SPECS = {}
fix = lambda i, **kw: SPECS[i].update(kw)

EXPOSE = ('It prints a ritual that the fraternity holds private, as a man who says he had been a member (or an outsider) wrote it down. Exposures of this kind vary in accuracy, were published to sell or to '
          'attack the Order, and each reports the degrees and the words of its own time and place; members say that the working of the degrees is theirs to give. The Library keeps it so that everyone '
          'can see what has been published and judge for themselves, and neither endorses the exposure nor its judgements of the Order. Understood, not endorsed.')
CRITIC = ('It is a hostile witness’s account of a sacred rite: its authors had left the church they describe, and the church’s own account of the rite is more reserved, and the rite itself has been '
          'changed since. Read it as what two people reported in their time, not as the church’s teaching. Understood, not endorsed.')
GRIM = 'A historical grimoire, kept here as a document in the history of magic and of folk belief, not as an endorsement and not as instructions.'
LONG_S = 'Eighteenth-century type (with the long s) read by OCR: a repair pass mends the commonest misreadings, but the text is rougher than most and some words are still wrong.'
OCC = 'Its claims are its authors’ own; the Library neither endorses nor judges them.'


def msx(i, idents, by, note, title, when, **kw):
    SPECS[i] = G(idents, by, note + ' ' + EXPOSE, lib=(title, 'ms', when, 'mas', None), **{'split': None, 'trim_index': False, **kw})


# ── The Masonic exposures ──
msx('k-prc', 'MasonryDissected', 'Samuel Prichard, Masonry Dissected: Being a Universal and Genuine Description of All Its Branches from the Original to This Present Time (London: J. Wilford, 1730)',
    'The first English printed exposure of the Masonic degrees, a few years after the Grand Lodge of 1717: a question-and-answer catechism of the Entered Apprentice, the Fellow Craft and the new third degree of Master Mason, with the story of Hiram. The author said he was a member and swore before an alderman of London that it was a true copy (the book prints the oath); the Grand Lodge answered with changes to its words. ' + LONG_S,
    'Masonry Dissected (Samuel Prichard, 1730)', '1730', long_s=True, cut_head=r'^\s*Masonry\s+Dif', cut_tail=r'^\s*BOOKS and PAMPHLETS')
msx('k-jab', 'cihm_47273', 'Jachin and Boaz; or, An Authentic Key to the Door of Free-Masonry, both Ancient and Modern, by a Gentleman belonging to the Jerusalem Lodge (London: W. Nicoll, 1762)',
    'A best-selling exposure of the English Masonic ritual of the 1760s (the Moderns’ working): the making of an Entered Apprentice, Fellow Craft and Master, the obligations, signs, grips and words of each degree, the opening of a lodge, the lectures, the Hiram legend, the installation of a master and the songs. Later editions kept it in print for sixty years. ' + LONG_S + ' This scan, from a microfilm, is rougher still.',
    'Jachin and Boaz, or an Authentic Key to the Door of Free-Masonry (1762)', '1762', long_s=True, cut_head=r'^\s*JACHIN\s+AND\s+BOAZ')
msx('k-tdk', 'the-three-distinct-knocks-or-the-door-of-the-most-antient-free-masonry-1785', 'The Three Distinct Knocks, or the Door of the Most Antient Free-Masonry Opening to All Men (first printed London, 1760; this is the Dublin printing of 1785, by T. Wilkinson)',
    'The exposure of the Ancients’ working of the Masonic degrees, the rival to the Moderns’ in Jachin and Boaz: the making of the Entered Apprentice, Fellow Craft and Master Mason, the three obligations, the lodge floor and the three steps, the examination of a brother, the songs, with the author’s reasons for opening the door. ' + LONG_S,
    'The Three Distinct Knocks (1760; Dublin printing of 1785)', '1760', long_s=True, cut_head=r'^\s*Three\s+di')
msx('k-mor', 'illustrationsofm00morg', 'William Morgan, Illustrations of Masonry, by One of the Fraternity Who Has Devoted Thirty Years to the Subject (Batavia, New York: printed for the author, 1826), part I',
    'The most famous exposure in American history: the first part of Morgan’s book, which prints the ritual of the Entered Apprentice, Fellow Craft and Master Mason degrees as the lodges in western New York worked them in the 1820s. Morgan was seized in September 1826 while the book was being printed, and the angry search for him (and the Masons who were tried for it) began the Anti-Masonic movement, which became America’s first third party. Part II (the higher degrees) was announced but this printing ends with part I.',
    'Illustrations of Masonry (William Morgan, 1826), part I', '1826', cut_head=r'^\s*ILLUSTRATIONS\s*$', cut_tail=r'^\.\s+\.,6rsJii')
msx('k-ber', 'lightonmasonrya00berngoog', 'David Bernard, Light on Masonry: A Collection of All the Most Important Documents on the Subject of Speculative Free Masonry (Utica: William Williams, 1829)',
    'The Anti-Masonic reference book of the Morgan affair: the proceedings of the Le Roy convention of seceding Masons (1828), with the ritual of the three degrees, of the Royal Arch and of the Knights Templar as the convention members said they had worked it, the renunciations of lodge officers and a large collection of oaths, documents, testimony and Anti-Masonic argument.',
    'Light on Masonry (David Bernard, 1829)', '1829', cut_tail=r'^\s*THE\s+BORROWER\s+WILL')
msx('k-aly', 'A_Ritual_Of_Freemasonry_-_A_Allyn', 'Avery Allyn, A Ritual of Freemasonry, Illustrated by Numerous Engravings, to Which Is Added a Key to the Phi Beta Kappa, the Orange, and Odd Fellows Societies, with Notes and Remarks (first published Philadelphia, 1831; this is the New York printing of William Gowans, 1853)',
    'An American exposure that sets out the whole of the York Rite working in the 1820s and 1830s: the three craft degrees, the Mark, Past and Most Excellent Master and the Royal Arch, the Royal and Select Master, and the Orders of Knighthood (the Red Cross, the Knights Templar and the Knights of Malta), the installations, the funeral service, with engravings, and a key to three other societies (Phi Beta Kappa, the Orange Order, the Odd Fellows). Allyn’s notes and his comments are hostile.',
    'A Ritual of Freemasonry (Avery Allyn, 1831; 1853 printing)', '1831')
msx('k-dun', 'duncan-s-masonic-ritual', 'Malcolm C. Duncan, Duncan’s Masonic Ritual and Monitor, or Guide to the Three Symbolic Degrees of the Ancient York Rite and to the Degrees of Mark Master, Past Master, Most Excellent Master, and the Royal Arch, Explained and Interpreted by Copious Notes and Numerous Engravings, third edition (New York: Dick & Fitzgerald, 1866); scanned at sacred-texts.com in January 2005 and proofed by John Bruno Hare, who gives the text to the public domain for any non-commercial purpose with his notice of attribution kept',
    'A printed guide to the York Rite as it was worked in the American lodges of the 1860s: the opening and closing of a lodge, the obligations, signs and words of the three craft degrees, the lectures, then the Mark Master, Past Master, Most Excellent Master and Royal Arch, with the author’s notes on the symbols and engravings. Published openly by a commercial house, and the Order’s members hold that the ritual is theirs to give. The text was keyed in at sacred-texts.com (2005, John Bruno Hare) and is in the public domain; the notice of attribution is kept here.',
    'Duncan’s Masonic Ritual and Monitor (Malcolm C. Duncan, 1866)', '1866', cut_head=r'^\s*PREFACE\s*$')

# ── Grimoires, magical rituals and the occult orders ──
SPECS['m-67m'] = G('sixthseventhbook00dela', 'The Sixth and Seventh Books of Moses, or Moses’ Magical Spirit-Art, Known as the Black Raven, the Magic of the Hebrews (Chicago: L. W. de Laurence, 1910 printing; a nineteenth-century German grimoire first printed in English in the United States)',
    'A grimoire that claims to be the lost books of Moses that the Hebrews used for their spirit-citations: Moses’ magical spirit-art, the table of the spirits and their seals, citations and conjurations, talismans and amulets, the spirit in the burning bush and the “helmet of Moses and Aaron”. A German compilation of the 1840s, probably no older, it spread in America through the German-language booksellers and the Chicago mail-order houses and has been a fixture of hoodoo, rootwork and the Pennsylvania German powwow traditions ever since. ' + GRIM + ' ' + OCC,
    lib=('The Sixth and Seventh Books of Moses (De Laurence printing of 1910)', 'oc', 'a German grimoire of the 1840s; English printing 1910', 'occ', None), split=None, trim_index=False, cut_tail=r'^\s*Deacidified using the Bookkeeper')
SPECS['m-alb'] = G('albertusmagnusbe00albe', 'Albertus Magnus: Being the Approved, Verified, Sympathetic and Natural Egyptian Secrets, or White and Black Art for Man and Beast, Revealing the Forbidden Knowledge of Ancient Philosophers (Chicago, c. 1900)',
    'A little book of folk magic and folk medicine: charms and remedies for people and for cattle, love charms, ways to keep witches from the butter, signs for the weather and for finding thieves, sympathetic magic and “Egyptian” secrets, set out in the old tradition of the German and Dutch “Albertus Magnus” and “Egyptian Secrets” chapbooks, which are not by the thirteenth-century saint and scholar whose name they carry. ' + GRIM + ' ' + OCC,
    lib=('Albertus Magnus: Egyptian Secrets (c. 1900 printing)', 'oc', 'folk magic; printed c. 1900 from an older chapbook', 'occ', None), split=None, trim_index=False)

# ── Greece, Egypt and the mystery religions ──
SPECS['x-mir'] = G('amythicritu06meaduoft', 'G. R. S. Mead, A Mithriac Ritual (Echoes from the Gnosis, vol. VI; London and Benares: Theosophical Publishing Society, 1907)',
    'Mead’s English of a long ritual from a magical papyrus in Paris (the “Great Magical Papyrus”, 4th century CE), which Albrecht Dieterich published in 1903 as a Mithras liturgy: the prayers and the spoken invocations by which the magician ascends through the heavens to see the god, with the sacrifices and the preparation. Mead’s title follows Dieterich; most scholars now think it is a magical rite of Roman Egypt that borrows from several cults and is not a liturgy of Mithras. It is here as an ancient ritual text, and as the nearest thing the Library has to a mystery rite in its own words.',
    lib=('A Mithriac Ritual (G. R. S. Mead, 1907)', 'gr', '2nd–4th c. CE (papyrus of the 4th c.)', 'grk', 'Isis and the Neoplatonists'), split=None, trim_index=False)
SPECS['x-elb'] = G('eleusinianbacch00tayluoft', 'Thomas Taylor, The Eleusinian and Bacchic Mysteries: A Dissertation, edited with introduction, notes, emendations and glossary by Alexander Wilder (New York: J. W. Bouton, 1891, fourth edition; Taylor first published the dissertation in 1790)',
    'The Platonist Thomas Taylor’s reconstruction of the Eleusinian and Bacchic mysteries from the Greek and Latin authors, with Wilder’s long introduction: what the Greater and Lesser Mysteries were, the stages of initiation, the myths of Demeter, Persephone and Dionysos, and Taylor’s view that the mysteries taught the immortality of the soul. It is a nineteenth-century reconstruction from the ancient writers, not a record of the rite (which the initiates kept secret); modern scholars of Eleusis start from the archaeology and the inscriptions, and disagree with parts of it.',
    lib=('The Eleusinian and Bacchic Mysteries (Thomas Taylor, ed. Wilder, 1891)', 'gr', 'c. 1500 BCE–392 CE (Taylor 1790; ed. 1891)', 'grk', 'The mysteries of Eleusis and Orpheus'), split=None, cut_tail=r'^\s*JUNE 1963')

# ── Theosophy and the Rosicrucian Fellowship ──
SPECS['v-sos'] = G('sciencesacramen00leadgoog', 'C. W. Leadbeater, The Science of the Sacraments (Adyar and London: Theosophical Publishing House, 1920)',
    'The Theosophist and bishop of the Liberal Catholic Church describes the Mass and the sacraments of that church (a church founded in 1916 on an Old Catholic line and shaped by Theosophists), step by step, as he said his clairvoyant sight showed what each part of the ritual does: the thought-forms, the angels, the flow of power in the Eucharist, baptism, confirmation, the blessing of the sacred vessels, ordination and the rest. The clairvoyant claims are his; the Library neither endorses nor judges them, and a reader who wants the church’s own account should read its liturgy.',
    lib=('The Science of the Sacraments (C. W. Leadbeater, 1920)', 'sp', 'published 1920 CE', 'spi', None), split='auto', min_chars=250, cut_head=r'^\s*PREFACE\s*$')
SPECS['v-hrc'] = G('rosicruciancos00hein', 'Max Heindel, The Rosicrucian Cosmo-Conception, or Christian Occult Science: An Elementary Treatise upon Man’s Past Evolution, Present Constitution and Future Development (Seattle: the Rosicrucian Fellowship, 1909)',
    'The founding book of the Rosicrucian Fellowship (Oceanside, California): the author’s account of the worlds and the regions of the cosmos, of man’s constitution, death and life after death, rebirth, the Christ and the future, which he said was given to him by an Elder Brother of the Rosicrucian order in 1907. His claims are his own, and are not those of the seventeenth-century Rosicrucian manifestos, which the Library holds apart. ' + OCC,
    lib=('The Rosicrucian Cosmo-Conception (Max Heindel, 1909)', 'sp', 'published 1909 CE', 'spi', None), split='auto', min_chars=250, cut_tail=r'^\s*INDEX\s*$')

# ── The Mormon temple endowment, as two who left it reported it ──
SPECS['x-vdu'] = G('startlingdisclos00vand', 'Increase McGee Van Dusen and Maria Van Dusen, Startling Disclosures of the Great Mormon Conspiracy against the Liberties of This Country: The Celebrated “Endowment,” as It Was Acted by Upwards of Twelve Thousand Men and Women in Secret in the Nauvoo Temple in 1846 (New York: published by Mr. and Mrs. Van Dusen, 1849; fifth edition)',
    'A husband and wife who joined the Church of Jesus Christ of Latter Day Saints, lived at Nauvoo for over three years, took part in the endowment in the Nauvoo Temple in the winter of 1845–46 and left, print what they said happened there: the washings and anointings, the garments, the instruction in the drama of the creation and the fall, the oaths and the signs and words. ' + CRITIC,
    lib=('Startling Disclosures of the Great Mormon Conspiracy (Van Dusen, 1849): the Nauvoo endowment', 'mo', 'recorded 1845–49 CE', 'mod', 'Bahá’í, Theosophy'), split=None, trim_index=False)
SPECS['x-mgr'] = G('fifteenyearsamon00greerich', 'Mary Ettie V. Smith (told to and edited by Nelson Winch Green), Fifteen Years among the Mormons: Being the Narrative of Mrs. Mary Ettie V. Smith, Late of Great Salt Lake City (New York: H. Dayton, 1858 or the Scribner printing of 1857 on the scan)',
    'The narrative of a woman brought up in the Mormon faith from childhood (her mother was baptized in Illinois), who lived at Nauvoo and then in Salt Lake City and left after fifteen years: the temple endowment in Nauvoo, plural marriage, the life of the households, Brigham Young and the leaders, and the migration to Utah, as she told it. ' + CRITIC,
    lib=('Fifteen Years among the Mormons (Mary Ettie V. Smith, 1857)', 'mo', 'recorded 1840s–50s CE', 'mod', 'Bahá’í, Theosophy'), split='auto', min_chars=250)

# ── Voodoo, Haiti and the Black South, as outsiders reported them before 1931 ──
SPECS['a-ovd'] = G('oldrabbitvoodooo00owen', 'Mary Alicia Owen, Old Rabbit, the Voodoo, and Other Sorcerers, with an introduction by Charles Godfrey Leland and a chapter on the Mississippi valley Indians (London: T. Fisher Unwin, 1893)',
    'Stories and sketches of conjurers and “voodoos” among the Black people of St. Joseph, Missouri, as a white woman collected them in the 1880s: the “conjure” doctors, the roots, the charms and the spirit-dancing of Old Rabbit and others, set beside the folk tales of the Sauk and Iowa Indians of the same district. Leland’s introduction reads the whole as survivals of African and Indian religion. ' + FIELD,
    lib=('Old Rabbit, the Voodoo, and Other Sorcerers (Mary Alicia Owen, 1893)', 'tf', 'recorded 1880s CE', 'fld', None), split=None, cut_head=r'^\s*INTRODUCTION\.\s*$', cut_tail=r'^\s*Printed in the United States')
SPECS['a-hti'] = G('whereblackrulesw00pric', 'Hesketh Hesketh-Prichard, Where Black Rules White: A Journey across and about Hayti (Westminster: Archibald Constable, 1900)',
    'An English traveller’s journey through Haiti in 1899: Port-au-Prince and the country, the black republic’s government and army, the churches, and the chapters on “Vaudoux” (its priests and priestesses, its snake worship, its ceremonies as he saw or was told of them, and its supposed human sacrifices). The stories of cannibal sacrifice that he and earlier visitors repeat were told by white and mulatto visitors and are not supported by other evidence; they are in the Library so that readers can see what was being said. ' + FIELD,
    lib=('Where Black Rules White: A Journey across and about Hayti (Hesketh Prichard, 1900)', 'tb', 'recorded 1899 CE', 'fld', None), split='auto', min_chars=250)

# ── Templars and a Maya theory ──
SPECS['x-tmp'] = G('historyofknights00addiuoft', 'Charles G. Addison, The History of the Knights Templars, the Temple Church, and the Temple (London: Longman, Brown, Green and Longmans, 1842)',
    'A barrister of the Temple’s history of the order of the Poor Knights of Christ and of the Temple of Solomon, from its founding at Jerusalem in about 1118 to its suppression in 1312: the Rule, the wealth, the quarrel with Philip the Fair, and the trials with the charges of denying Christ, spitting on the cross and worshipping an idol, with the evidence of the witnesses. A book of its time (it is sympathetic to the Templars), and an early source of the Masonic and occult stories about them. ' + SCH,
    lib=S('The History of the Knights Templars (Charles G. Addison, 1842)', '1118–1312 CE'), split='auto', min_chars=250)
SPECS['a-lpl'] = G('sacredmysteriesa00leplrich', 'Augustus Le Plongeon, Sacred Mysteries among the Mayas and the Quiches, 11,500 Years Ago: Their Relation to the Sacred Mysteries of Egypt, Greece, Chaldea and India; Free Masonry in Times Anterior to the Temple of Solomon (New York: Robert Macoy, 1886)',
    'A photographer and amateur archaeologist, who had dug at Chichén Itzá and Uxmal, argues that the Maya were the oldest civilisation, that they colonised Egypt and the Near East, and that the Masonic mysteries began in Yucatán. Archaeologists reject his dating of the Maya buildings and his reading of the glyphs, and Maya civilisation is nowhere near as old as he says; the book is here as the source of a long-lived occult belief (“Mu” and the Masonic Maya) and as a record of what he saw at the sites. Read it as the case of one man, and as a popular claim.',
    lib=('Sacred Mysteries among the Mayas and the Quiches (Augustus Le Plongeon, 1886)', 'tb', 'recorded 1870s–80s CE', 'fld', None), split='auto', min_chars=250, cut_tail=r'^Aac, his history')

# ── Books once left out by judgment ──
SPECS['x-jng'] = G('psychologyofunco00junguoft', 'C. G. Jung, Psychology of the Unconscious: A Study of the Transformations and Symbolisms of the Libido, a Contribution to the History of the Evolution of Thought, translated by Beatrice M. Hinkle (New York: Moffat, Yard, 1916; first German edition 1911–12)',
    'The book that broke Jung’s friendship with Freud: a long study of the myths of the hero, the dying god and the sun and of the religious symbols (the Christian, Mithraic and Hindu among them) that he saw in the fantasies of a young American woman and in Longfellow’s Hiawatha, read as the working of the unconscious. A work of psychology and of its time (Jung rewrote it in 1952 as Symbols of Transformation); the Library holds it as scholarship about myth and religion, and does not endorse its method. ' + SCH,
    lib=S('Psychology of the Unconscious (C. G. Jung, 1916)', 'published 1912–16 CE'), split='auto', min_chars=250, cut_tail=r'^\s*I\s?NDEX\s*$', cut_tail_from=0.9)
SPECS['x-kau'] = G('in.ernet.dli.2015.102722', 'Kautilya, Kautilya’s Arthasastra, translated by R. Shamasastry, with an introductory note by J. F. Fleet (Mysore, 1915; second edition 1923; this scan, from the Digital Library of India, is a later Mysore Printing and Publishing House reprint of the third edition of 1929)',
    'The ancient Indian treatise on kingship and statecraft, attributed to Kautilya (Chanakya), the minister of Chandragupta Maurya, in fifteen books: the duties of the king and his officers, the courts and the law, the spies, the army, and the rules for temples, priests and ascetics, for festivals and for public sacrifices. Not a religious text, but the earliest source of the state’s dealings with religion in India, and often cited by it.',
    lib=S('Kautilya’s Arthashastra (trans. R. Shamasastry, 1915)', 'c. 300 BCE–300 CE'), split='auto', min_chars=250)

# ── The Nusayri (Alawite) secret book, as a convert disclosed it ──
SPECS['x-nsr'] = G('sim_journal-of-the-american-oriental-society_1866_8', 'Edward E. Salisbury, Notice of the Book of Sulaiman’s First Ripe Fruit, Disclosing the Mysteries of the Nusairian Religion, by Sulaiman Effendi of Adhanah, with Copious Extracts (Journal of the American Oriental Society, vol. 8, article VI; New Haven, 1866, read to the Society in 1864)',
    'The Nusayri (Alawite) religion of Syria, whose books and rites its members keep from outsiders, as one of its own people told it: Sulaiman of Adana, who had been born into the sect, was initiated and then became a Protestant, wrote out the Book of the First Ripe Fruit in Arabic in 1863, and Salisbury, a professor at Yale, translated and summarised it with long extracts: Sulaiman’s own initiation, the doctrines (the divinity of Ali, the triad of the Meaning, the Name and the Gate, the transmigration of souls), the rites and feasts (the Mass of the Nusayris, the wine, the feasts of the Persians and Christians they adopt) and specimens of their poetry and prayers. ' + 'It is the account of a convert, who wrote against the faith he had left, and it is the fullest English report of its secret teaching before 1931. The Nusayris (Alawites) hold their teaching secret from outsiders and from most of their own people, and the Library keeps the book so that everyone can see what was published and judge for themselves; it neither endorses it nor its judgements of the sect. Understood, not endorsed.',
    lib=S('The Book of Sulaiman’s First Ripe Fruit: the mysteries of the Nusairian religion (E. E. Salisbury, 1866)', 'recorded 1863–64 CE'),
    slice=(r'^ARTICLE VI\.\s*$', r'^ARTICLE VII\.\s*$'), split=None, trim_index=False, trim_front=False, trim_back=False)
